import React from 'react';
import { Link } from 'react-router-dom';

const Cursos = () => {
  const cursos = [
    { id: 1, nombre: 'Curso de React', descripcion: 'Aprende a desarrollar aplicaciones web con React.' },
    { id: 2, nombre: 'Curso de JavaScript', descripcion: 'Domina el lenguaje de programación JavaScript.' }
  ];

  return (
    <div className="cursos">
      <h1>Nuestros Cursos</h1>
      <div className="curso-lista">
        {cursos.map((curso) => (
          <div className="curso" key={curso.id}>
            <h2>{curso.nombre}</h2>
            <p>{curso.descripcion}</p>
            <Link to={`/curso-detalle/${curso.id}`}>Ver detalles</Link>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Cursos;
